import 'package:dio/dio.dart';import 'package:flutter/material.dart';import 'package:flutter_localizations/flutter_localizations.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:flutter_secure_storage/flutter_secure_storage.dart';import 'package:url_launcher/url_launcher.dart';import 'core/api.dart';import 'core/models.dart';
final storageProvider=Provider((_)=>const FlutterSecureStorage());final apiProvider=Provider((r){final a=Api(r.read(storageProvider));a.init();return a;});final ordersProvider=FutureProvider<List<Order>>((r)async{final res=await r.read(apiProvider).dio.get('/orders',queryParameters:{'date':DateTime.now().toIso8601String().substring(0,10)});return ((res.data['data']['data'])as List).map((e)=>Order.fromJson(e)).toList();});
void main()=>runApp(const ProviderScope(child:App()));class App extends StatelessWidget{const App({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,locale:const Locale('fa'),supportedLocales:const[Locale('fa')],localizationsDelegates:GlobalMaterialLocalizations.delegates,theme:ThemeData(colorSchemeSeed:Colors.teal,fontFamily:'sans'),home:const Gate());}
class Gate extends ConsumerWidget{const Gate({super.key});@override Widget build(c,r)=>FutureBuilder(future:r.read(storageProvider).read(key:'token'),builder:(c,s){if(!s.hasData)return const Scaffold(body:Center(child:CircularProgressIndicator()));return s.data==null?const Login():const Shell();});}
class Login extends ConsumerStatefulWidget{const Login({super.key});@override ConsumerState<Login> createState()=>_LoginState();}class _LoginState extends ConsumerState<Login>{final login=TextEditingController(),password=TextEditingController();bool loading=false;Future<void> submit()async{setState(()=>loading=true);try{final x=await ref.read(apiProvider).dio.post('/login',data:{'login':login.text,'password':password.text,'device_name':'Visitor Android'});await ref.read(storageProvider).write(key:'token',value:x.data['data']['token']);if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>const Shell()));}on DioException catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ارتباط با سرور برقرار نشد یا اطلاعات ورود نادرست است.')));}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(c)=>Scaffold(body:SafeArea(child:Padding(padding:const EdgeInsets.all(28),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[const Text('سامانه تحویل سفارش',style:TextStyle(fontSize:26,fontWeight:FontWeight.bold)),const SizedBox(height:30),TextField(controller:login,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'شماره موبایل یا نام کاربری')),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'رمز عبور')),const SizedBox(height:24),FilledButton(onPressed:loading?null:submit,style:FilledButton.styleFrom(minimumSize:const Size.fromHeight(52)),child:loading?const CircularProgressIndicator():const Text('ورود'))]))));}
class Shell extends ConsumerStatefulWidget{const Shell({super.key});@override ConsumerState<Shell> createState()=>_ShellState();}class _ShellState extends ConsumerState<Shell>{int tab=0;@override Widget build(c){final pages=[const Home(),const Orders(),const Report(),const Profile()];return Scaffold(body:pages[tab],bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(v)=>setState(()=>tab=v),destinations:const[NavigationDestination(icon:Icon(Icons.home_outlined),label:'خانه'),NavigationDestination(icon:Icon(Icons.list_alt),label:'سفارش‌ها'),NavigationDestination(icon:Icon(Icons.bar_chart),label:'گزارش من'),NavigationDestination(icon:Icon(Icons.person_outline),label:'پروفایل')]));}}
class Home extends ConsumerWidget{const Home({super.key});@override Widget build(c,r){final a=r.watch(ordersProvider);return Scaffold(appBar:AppBar(title:const Text('خانه')),body:a.when(data:(x){final done=x.where((o)=>o.status=='delivered').length;return Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('امروز ${DateTime.now().toLocal().toString().substring(0,10)}',style:const TextStyle(fontSize:18)),const SizedBox(height:20),Wrap(spacing:12,runSpacing:12,children:[Stat('سفارش امروز',x.length),Stat('تحویل شده',done),Stat('باقی مانده',x.length-done)]),const SizedBox(height:28),FilledButton(onPressed:()=>DefaultTabController.of(c),child:const Text('مشاهده سفارش‌های امروز'))]));},error:(_,__)=>const Center(child:Text('ارتباط با سرور برقرار نشد.')),loading:()=>const Center(child:CircularProgressIndicator()));}}
class Stat extends StatelessWidget{const Stat(this.t,this.n,{super.key});final String t;final int n;@override Widget build(c)=>Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(children:[Text('$n',style:const TextStyle(fontSize:25,fontWeight:FontWeight.bold)),Text(t)])));}
class Orders extends ConsumerWidget{const Orders({super.key});@override Widget build(c,r){final a=r.watch(ordersProvider);return Scaffold(appBar:AppBar(title:const Text('سفارش‌های امروز')),body:RefreshIndicator(onRefresh:()=>refread(r),child:a.when(data:(x)=>x.isEmpty?const ListView(children:[SizedBox(height:250),Center(child:Text('سفارشی برای امروز ثبت نشده است.'))]):ListView.builder(itemCount:x.length,itemBuilder:(c,i)=>OrderCard(x[i])),error:(_,__)=>ListView(children:[const SizedBox(height:250),const Center(child:Text('ارتباط با سرور برقرار نشد. دوباره تلاش کنید.'))]),loading:()=>const Center(child:CircularProgressIndicator()))));}Future<void> refread(WidgetRef r)=>r.refresh(ordersProvider.future);}
class OrderCard extends StatelessWidget{const OrderCard(this.o,{super.key});final Order o;@override Widget build(c)=>Card(child:ListTile(onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>OrderDetail(o))),title:Text('سفارش #${o.number}'),subtitle:Text('${o.customer['company_name']??o.customer['name']}\nوزن: ${o.weight} kg'),trailing:Text('${o.amount} تومان\n${o.status}',textAlign:TextAlign.end)));}
class OrderDetail extends ConsumerWidget{const OrderDetail(this.order,{super.key});final Order order;Future<void> call()async{final u=Uri(scheme:'tel',path:order.customer['mobile']);await launchUrl(u);}Future<void> start(BuildContext c,WidgetRef r)async{try{await r.read(apiProvider).dio.post('/orders/${order.id}/start-delivery');if(c.mounted)Navigator.push(c,MaterialPageRoute(builder:(_)=>Verify(order)));}catch(_){if(c.mounted)ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('امکان شروع تحویل وجود ندارد.')));}}@override Widget build(c,r)=>Scaffold(appBar:AppBar(title:Text('سفارش #${order.number}')),body:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(order.customer['name']??'',style:const TextStyle(fontSize:22)),Text(order.customer['address']??''),const SizedBox(height:20),Text('مبلغ: ${order.amount} تومان'),Text('وزن: ${order.weight} kg'),const Spacer(),Row(children:[OutlinedButton.icon(onPressed:call,icon:const Icon(Icons.call),label:const Text('تماس')),const SizedBox(width:12),Expanded(child:FilledButton(onPressed:()=>start(c,r),child:const Text('شروع تحویل')))])]));}
class Verify extends ConsumerStatefulWidget{const Verify(this.o,{super.key});final Order o;@override ConsumerState<Verify>createState()=>_VerifyState();}class _VerifyState extends ConsumerState<Verify>{final code=TextEditingController();bool busy=false;Future<void> verify()async{setState(()=>busy=true);try{await ref.read(apiProvider).dio.post('/orders/${widget.o.id}/verify-delivery-code',data:{'code':code.text});if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>PaymentPage(widget.o)));}on DioException catch(e){final d=e.response?.data;final msg=d is Map<String,dynamic>?d['message']?.toString()??'کد صحیح نیست.':'برای تأیید کد اتصال اینترنت لازم است.';if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(msg)));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(c)=>Scaffold(appBar:AppBar(title:const Text('تأیید تحویل سفارش')),body:Padding(padding:const EdgeInsets.all(24),child:Column(children:[Text('سفارش #${widget.o.number}'),Text(widget.o.customer['name']??''),TextField(controller:code,maxLength:6,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'کد ۶ رقمی')),const SizedBox(height:18),FilledButton(onPressed:busy?null:verify,style:FilledButton.styleFrom(minimumSize:const Size.fromHeight(52)),child:const Text('بررسی کد'))])));}}
class PaymentPage extends ConsumerStatefulWidget{const PaymentPage(this.o,{super.key});final Order o;@override ConsumerState<PaymentPage>createState()=>_PaymentState();}class _PaymentState extends ConsumerState<PaymentPage>{String method='card';final amount=TextEditingController();final reference=TextEditingController();bool busy=false;Future<void> submit()async{setState(()=>busy=true);try{await ref.read(apiProvider).dio.post('/orders/${widget.o.id}/payment',data:{'method':method,'amount':int.tryParse(amount.text.replaceAll(',',''))??widget.o.amount,'reference_number':reference.text});await ref.read(apiProvider).dio.post('/orders/${widget.o.id}/complete-delivery',data:{'idempotency_key':'${widget.o.id}-${DateTime.now().millisecondsSinceEpoch}'});if(mounted)Navigator.pushReplacement(context,MaterialPageRoute(builder:(_)=>Receipt(widget.o,method)));}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('ثبت تحویل ناموفق بود. دوباره تلاش کنید.')));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(c)=>Scaffold(appBar:AppBar(title:const Text('روش تسویه')),body:Padding(padding:const EdgeInsets.all(20),child:Column(children:[DropdownButtonFormField(value:method,items:const[DropdownMenuItem(value:'card',child:Text('کارت')),DropdownMenuItem(value:'cash',child:Text('نقد')),DropdownMenuItem(value:'cheque',child:Text('چک')),DropdownMenuItem(value:'credit',child:Text('اعتباری')),DropdownMenuItem(value:'bank_transfer',child:Text('واریز بانکی')),DropdownMenuItem(value:'prepaid',child:Text('قبلاً پرداخت شده'))],onChanged:(v)=>setState(()=>method=v!)),TextField(controller:amount,keyboardType:TextInputType.number,decoration:InputDecoration(labelText:'مبلغ (پیشنهادی: ${widget.o.amount})')),TextField(controller:reference,decoration:const InputDecoration(labelText:'شماره پیگیری')),const Spacer(),FilledButton(onPressed:busy?null:submit,style:FilledButton.styleFrom(minimumSize:const Size.fromHeight(52)),child:const Text('تأیید نهایی تحویل'))])));}}
class Receipt extends StatelessWidget{const Receipt(this.o,this.method,{super.key});final Order o;final String method;@override Widget build(c)=>Scaffold(appBar:AppBar(title:const Text('رسید تحویل')),body:Center(child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[const Icon(Icons.check_circle,color:Colors.green,size:72),const Text('تحویل با موفقیت ثبت شد.',style:TextStyle(fontSize:22)),Text('سفارش: ${o.number}'),Text('مشتری: ${o.customer['name']}'),Text('روش پرداخت: $method'),Text('زمان: ${DateTime.now()}')])));}
class Report extends StatelessWidget{const Report({super.key});@override Widget build(c)=>Scaffold(appBar:AppBar(title:const Text('گزارش من')),body:const Center(child:Text('گزارش امروز، این هفته و این ماه از سرور نمایش داده می‌شود.')));}
class Profile extends ConsumerWidget{const Profile({super.key});@override Widget build(c,r)=>Scaffold(appBar:AppBar(title:const Text('پروفایل')),body:Padding(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('نسخه برنامه 1.0.0'),const Spacer(),FilledButton.tonal(onPressed:()async{final ok=await showDialog<bool>(context:c,builder:(x)=>AlertDialog(title:const Text('خروج'),content:const Text('آیا از خروج مطمئن هستید؟'),actions:[TextButton(onPressed:()=>Navigator.pop(x),child:const Text('خیر')),FilledButton(onPressed:()=>Navigator.pop(x,true),child:const Text('بله'))]));if(ok==true){await r.read(storageProvider).delete(key:'token');if(c.mounted)Navigator.pushAndRemoveUntil(c,MaterialPageRoute(builder:(_)=>const Login()),(_)=>false);}},child:const Text('خروج از حساب'))])));}
